#include <arpa/inet.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// ...

// Receive number from client
uint32_t receivedData;
socklen_t client_addr_size = sizeof(client_addr);
ssize_t bytes_received = recvfrom(server_socket, &receivedData, sizeof(uint32_t), 0, (struct sockaddr *)&client_addr, &client_addr_size);

if (bytes_received == -1) {
    perror("recvfrom");
    // Handle error, e.g., close the socket and exit
    close(server_socket);
    exit(EXIT_FAILURE);
}

if (bytes_received != sizeof(uint32_t)) {
    fprintf(stderr, "Received unexpected number of bytes: %zd\n", bytes_received);
    // Handle error, e.g., close the socket and exit
    close(server_socket);
    exit(EXIT_FAILURE);
}

uint32_t bigEndianData = ntohl(receivedData);
printf("Client: %u\n", bigEndianData); // Use %u for unsigned integers
